// clnRawMessages converts CLN raw JSON entries into the common raw message response format.
func clnRawMessages(implementation string, entries []json.RawMessage, timestamp func(json.RawMessage) (time.Time, error)) ([]RawMessage, *ResponseRawPagination, error) {
	respPagination := &ResponseRawPagination{UseTimestamp: true}
	ret := make([]RawMessage, 0, len(entries))

	minTime := time.Unix(1<<63-1, 0)
	maxTime := time.Unix(0, 0)

	for _, one := range entries {
		t, err := timestamp(one)
		if err != nil {
			return nil, respPagination, err
		}

		if t.Before(minTime) {
			minTime = t
		}
		if t.After(maxTime) {
			maxTime = t
		}

		m := RawMessage{
			Implementation: implementation,
			Timestamp:      t,
			Message:        one,
		}

		ret = append(ret, m)
	}

	respPagination.FirstTime = minTime
	respPagination.LastTime = maxTime

	return ret, respPagination, nil
}

// GetInvoicesRaw - API call
func (l *ClnSocketLightningAPI) GetInvoicesRaw(ctx context.Context, pendingOnly bool, pagination RawPagination) ([]RawMessage, *ResponseRawPagination, error) {
	var (
		reply   ClnRawInvoices
		gettime ClnRawInvoiceTime
	)

	respPagination := &ResponseRawPagination{UseTimestamp: true}

	err := l.CallWithTimeout(LISTINVOICES, []interface{}{}, &reply)
	if err != nil {
		return nil, respPagination, err
	}

	return clnRawMessages(l.Name, reply.Entries, func(one json.RawMessage) (time.Time, error) {
		err := json.Unmarshal(one, &gettime)
		if err != nil {
			return time.Time{}, err
		}

		return time.Unix(int64(gettime.Time), 0), nil
	})
}

